import json

# Let me check the JSON files for any 2025 estimate
with open('/app/resources/treasury_bulletin_2014_06.json', 'r') as f:
    data = json.load(f)

# Search for 2025
def search_json(obj, path=""):
    results = []
    if isinstance(obj, dict):
        for key, value in obj.items():
            if "2025" in str(key):
                results.append(f"Found 2025 in key: {path}/{key}")
            results.extend(search_json(value, f"{path}/{key}"))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_json(item, f"{path}[{i}]"))
    elif isinstance(obj, str):
        if "2025" in obj:
            results.append(f"Found 2025 in string: {path} = {obj[:100]}")
    return results

results = search_json(data)
for r in results:
    print(r)

if not results:
    print("No 2025 found in 2014 bulletin JSON")
